import os
from app import config, registry

class TestPricing:
    discounts = {}

    def test_apply_discount(self):
        self.discounts["vip"] = 0.2
        assert price(100, self.discounts) == 80

    def test_no_discount(self):
        assert price(100, self.discounts) == 100


def test_feature_flag_on():
    os.environ["FEATURE_X"] = "1"
    registry.reload()
    assert registry.enabled("x")


def test_default_currency():
    assert config.currency() == "USD"
